CREATE INDEX idx_contenedor_sector ON contenedor (sector_id);

-- Quedan 4 camiones, uno por sector, todos saliendo de la base de la zona 1
ALTER TABLE camion ADD COLUMN sector_id INTEGER REFERENCES sector (id);
DELETE FROM camion WHERE id NOT IN ('C22', 'C31', 'C14', 'C17');
DELETE FROM dispositivo WHERE usuario_id IN (SELECT id FROM usuario WHERE rol = 'chofer'
    AND id NOT IN (SELECT chofer_id FROM camion WHERE chofer_id IS NOT NULL));
DELETE FROM usuario WHERE rol = 'chofer' AND id NOT IN (SELECT chofer_id FROM camion WHERE chofer_id IS NOT NULL);
UPDATE camion SET zona_id = 1, sector_id = 1, estado = 'en_base', carga_pct = 0, km_recorridos_hoy = 0, lat = (SELECT base_lat FROM zona WHERE id = 1), lng = (SELECT base_lng FROM zona WHERE id = 1) WHERE id = 'C22';
UPDATE camion SET zona_id = 1, sector_id = 2, estado = 'en_base', carga_pct = 0, km_recorridos_hoy = 0, lat = (SELECT base_lat FROM zona WHERE id = 1), lng = (SELECT base_lng FROM zona WHERE id = 1) WHERE id = 'C31';
UPDATE camion SET zona_id = 1, sector_id = 3, estado = 'en_base', carga_pct = 0, km_recorridos_hoy = 0, lat = (SELECT base_lat FROM zona WHERE id = 1), lng = (SELECT base_lng FROM zona WHERE id = 1) WHERE id = 'C14';
UPDATE camion SET zona_id = 1, sector_id = 4, estado = 'en_base', carga_pct = 0, km_recorridos_hoy = 0, lat = (SELECT base_lat FROM zona WHERE id = 1), lng = (SELECT base_lng FROM zona WHERE id = 1) WHERE id = 'C17';
ALTER TABLE camion ALTER COLUMN sector_id SET NOT NULL;
